		}
		u.Scopes = effective
		u.KeyID = initial.KeyID
	}
	if !hasString(u.Scopes, "findings:write") || !hasString(u.Scopes, "findings:read") {
		return u, findingBulkError{403, "현재 발견 건 조회·수정 권한이 없습니다"}
	}
	return u, nil
